function validate([grid, queries]) {
  if (!Array.isArray(grid) || grid.length < 2 || grid.length > 1000) return 'grid needs 2 to 1000 rows.';
  const n = grid[0].length;
  if (n < 2 || n > 1000) return 'Each row needs 2 to 1000 values.';
  if (grid.some(row => row.length !== n)) return 'All rows must have the same length.';
  if (grid.length * n < 4 || grid.length * n > 100000) return 'grid holds 4 to 10^5 cells.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 1000000))) return 'Each cell is an integer from 1 to 10^6.';
  if (queries.length < 1 || queries.length > 10000) return 'queries needs 1 to 10^4 values.';
  if (queries.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each query is an integer from 1 to 10^6.';
  return null;
}

