function maxPoints(grid, queries) {
  const rows = grid.length;
  const cols = grid[0].length;
  const order = queries.map((_, i) => i).sort((a, b) => queries[a] - queries[b]);
  const answer = new Array(queries.length).fill(0);
  const visited = grid.map(row => row.map(() => false));
  const heap = [];
  const push = (value, row, col) => {
    heap.push([value, row, col]);
    let child = heap.length - 1;
    while (child > 0 && heap[(child - 1) >> 1][0] > heap[child][0]) {
      const parent = (child - 1) >> 1;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    while (true) {
      let smallest = parent;
      const left = 2 * parent + 1;
      const right = left + 1;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === parent) break;
      [heap[parent], heap[smallest]] = [heap[smallest], heap[parent]];
      parent = smallest;
    }
    return top;
  };

  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  visited[0][0] = true;
  push(grid[0][0], 0, 0);
  let points = 0;
  for (const index of order) {
    while (heap.length > 0 && heap[0][0] < queries[index]) {
      const [, row, col] = pop();
      points++;
      for (const [dr, dc] of directions) {
        const nextRow = row + dr;
        const nextCol = col + dc;
        if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
        if (visited[nextRow][nextCol]) continue;
        visited[nextRow][nextCol] = true;
        push(grid[nextRow][nextCol], nextRow, nextCol);
      }
    }
    answer[index] = points;
  }
  return answer;
}

