function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const m = int(60, 100), n = int(60, 100);
    const top = rand() < 0.5 ? 1000000 : 1000;
    const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => int(1, top)));
    const queries = Array.from({ length: 2000 }, () => int(1, top));
    return [grid, queries];
  }
  const m = int(2, 4), n = int(2, 4);
  const top = int(2, 12);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => int(1, top)));
  const queries = Array.from({ length: int(1, 6) }, () => int(1, top + 1));
  return [grid, queries];
}
